    13→export default function ResultsBar({ page, totalProducts, onPageChange }: ResultsBarProps) {
    14→  const [visible, setVisible] = useState(false);
    15→  const perPage = 15;
    16→  const totalPages = Math.ceil(totalProducts / perPage) || 1;
    17→
    18→  useEffect(() => {
    19→    fetch(`${API_URL}/api/results-bar`)
    20→      .then(r => r.json())
    21→      .then(data => setVisible(data.visible));
    22→  }, []);
